diff --git a/tests/options.optsWithGlobals.test.js b/tests/options.optsWithGlobals.test.js
index 0f84454..6ec53b9 100644
--- a/tests/options.optsWithGlobals.test.js
+++ b/tests/options.optsWithGlobals.test.js
@@ -68,6 +68,73 @@ describe('Command.optsWithGlobals()', () => {
 });

 describe('getOptionValueSourceWithGlobals', () => {
+  for (const value of ['global value', false, 0, '', undefined]) {
+    test(`when global value is ${JSON.stringify(value)} with unknown source then it masks child source`, () => {
+      const program = new commander.Command();
+      const sub = program.command('sub');
+      program.setOptionValue('common', value);
+      sub.setOptionValueWithSource('common', 'local value', 'cli');
+
+      assert.deepEqual(sub.optsWithGlobals(), { common: value });
+      assert.equal(sub.getOptionValueSourceWithGlobals('common'), undefined);
+    });
+  }
+
+  for (const source of ['default', 'config', 'env', 'cli', 'implied']) {
+    test(`when global source is ${source} then it overrides child source`, () => {
+      const program = new commander.Command();
+      const sub = program.command('sub');
+      program.setOptionValueWithSource('common', 'global value', source);
+      sub.setOptionValueWithSource('common', 'local value', 'cli');
+
+      assert.deepEqual(sub.optsWithGlobals(), { common: 'global value' });
+      assert.equal(sub.getOptionValueSourceWithGlobals('common'), source);
+    });
+  }
+
+  test('when parent option has no value then child source is preserved', () => {
+    const program = new commander.Command().option('--common <value>');
+    const sub = program.command('sub');
+    sub.setOptionValueWithSource('common', 'local value', 'cli');
+
+    assert.deepEqual(sub.optsWithGlobals(), { common: 'local value' });
+    assert.equal(sub.getOptionValueSourceWithGlobals('common'), 'cli');
+    assert.equal(sub.getOptionValueSourceWithGlobals('missing'), undefined);
+  });
+
+  test('when nested global value has unknown source then it masks child source', () => {
+    const program = new commander.Command();
+    const sub = program.command('sub');
+    const subsub = sub.command('subsub');
+    sub.setOptionValue('common', 'middle value');
+    subsub.setOptionValueWithSource('common', 'local value', 'cli');
+
+    assert.deepEqual(subsub.optsWithGlobals(), { common: 'middle value' });
+    assert.equal(subsub.getOptionValueSourceWithGlobals('common'), undefined);
+
+    program.setOptionValueWithSource('common', 'global value', 'config');
+    assert.deepEqual(subsub.optsWithGlobals(), { common: 'global value' });
+    assert.equal(subsub.getOptionValueSourceWithGlobals('common'), 'config');
+
+    program.setOptionValue('common', 'unknown global value');
+    assert.deepEqual(subsub.optsWithGlobals(), {
+      common: 'unknown global value',
+    });
+    assert.equal(subsub.getOptionValueSourceWithGlobals('common'), undefined);
+  });
+
+  test('when global value is stored as property with unknown source then it masks child source', () => {
+    const program = new commander.Command()
+      .storeOptionsAsProperties()
+      .option('--common <value>');
+    const sub = program.command('sub');
+    program.setOptionValue('common', 'global value');
+    sub.setOptionValueWithSource('common', 'local value', 'cli');
+
+    assert.deepEqual(sub.optsWithGlobals(), { common: 'global value' });
+    assert.equal(sub.getOptionValueSourceWithGlobals('common'), undefined);
+  });
+
