 });

 describe('getOptionValueSourceWithGlobals', () => {
+  test('an unset parent option preserves the same named child value and source', () => {
+    const program = new commander.Command().option('--common <value>');
+    const sub = program.command('sub').option('--common <value>');
+    sub.setOptionValueWithSource('common', 'child', 'cli');
