@@ -114,3 +123,72 @@ describe('getOptionValueSourceWithGlobals', () => {
     assert.equal(sub.getOptionValueSourceWithGlobals('common'), 'default');
   });
 });
+
+// Source precedence follows the option values, including unknown sources.
+for (const storeAsProperties of [false, true]) {
+  describe(`global sources with storeOptionsAsProperties(${storeAsProperties})`, () => {
+    for (const value of ['parent', false, 0, '', null, undefined]) {
+      test(`parent value ${JSON.stringify(value)} with unknown source masks child source`, () => {
+        const program = new commander.Command()
+          .storeOptionsAsProperties(storeAsProperties)
+          .option('--common <value>');
+        const sub = program.command('sub').option('--common <value>');
+        program.setOptionValue('common', value);
+        sub.setOptionValueWithSource('common', 'child', 'cli');
+
+        assert.deepEqual(sub.optsWithGlobals(), { common: value });
+        assert.equal(sub.getOptionValueSourceWithGlobals('common'), undefined);
+      });
+    }
+
+    for (const source of ['default', 'config', 'env', 'cli', 'implied']) {
+      test(`recognized parent source ${source} overrides child source`, () => {
+        const program = new commander.Command()
+          .storeOptionsAsProperties(storeAsProperties)
+          .option('--common <value>');
+        const sub = program.command('sub').option('--common <value>');
+        program.setOptionValueWithSource('common', 'parent', source);
+        sub.setOptionValueWithSource('common', 'child', 'cli');
+
+        assert.deepEqual(sub.optsWithGlobals(), { common: 'parent' });
+        assert.equal(sub.getOptionValueSourceWithGlobals('common'), source);
+      });
+    }
+
+    test('unknown source on intermediate command masks nested child source', () => {
+      const program = new commander.Command().storeOptionsAsProperties(
+        storeAsProperties,
+      );
+      const sub = program.command('sub').option('--common <value>');
+      const nested = sub
+        .command('nested')
+        .option('--common <value>')
+        .option('--local <value>');
+      sub.setOptionValue('common', 'parent');
+      nested.setOptionValueWithSource('common', 'child', 'cli');
+      nested.setOptionValueWithSource('local', 'local value', 'cli');
+
+      assert.deepEqual(nested.optsWithGlobals(), {
+        common: 'parent',
+        local: 'local value',
+      });
+      assert.equal(nested.getOptionValueSourceWithGlobals('common'), undefined);
+      assert.equal(nested.getOptionValueSourceWithGlobals('local'), 'cli');
+      assert.equal(nested.getOptionValueSourceWithGlobals('missing'), undefined);
+    });
+
+    test('outermost unknown source masks recognized sources at both nested levels', () => {
+      const program = new commander.Command()
+        .storeOptionsAsProperties(storeAsProperties)
+        .option('--common <value>');
+      const sub = program.command('sub').option('--common <value>');
+      const nested = sub.command('nested').option('--common <value>');
+      program.setOptionValue('common', 'root');
+      sub.setOptionValueWithSource('common', 'parent', 'config');
+      nested.setOptionValueWithSource('common', 'child', 'cli');
+
+      assert.deepEqual(nested.optsWithGlobals(), { common: 'root' });
+      assert.equal(nested.getOptionValueSourceWithGlobals('common'), undefined);
+    });
+  });
+}

